        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#OUBLI&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Oubli&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#POSSESSION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Possession&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#VENGEANCE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Vengeance&lt;/a&gt;&lt;/td&gt;
